-- ============================================================================
-- payer-rules-coverage-basis-aetna-anthem.sql
--
-- WHY THIS EXISTS
-- Aetna and Anthem BCBS Ohio had ZERO 'covered' rules. The only ones they
-- ever had were seven rows a person typed by hand (created_by
-- 'test@pallio.io'), withdrawn in commit d1ba7a5 because nothing backed
-- them. Withdrawing them did not create the gap -- it revealed one that had
-- been masked since the library was built.
--
-- WHAT WAS SEARCHED, AND WHAT WAS NOT FOUND
-- All 919 live Aetna medical Clinical Policy Bulletins (the number space
-- 0001-1300 was enumerated directly, twice, because Aetna's own indexes are
-- stale and its search UI is client-rendered). Exactly one CPB contains any
-- of these codes -- CPB 0730, Home Behavioral Healthcare Services -- and
-- there the codes sit under "Other CPT codes related to the CPB:", a bucket
-- Aetna keeps deliberately distinct from "CPT codes covered if selection
-- criteria are met" (CPB 0201 carries both headings and proves the
-- distinction). Building a coverage rule on that placement would have been
-- the same fabrication this seed exists to replace, so it was not done.
--
-- Two other well-evidenced routes were rejected on scope, not on quality:
--   * Ohio Medicaid's Appendix DD fee schedule plus OAC 5160-26-03 (an MCO
--     "must ensure members have access to all medically necessary" covered
--     services) would ground coverage for a Medicaid managed care plan.
--     Both of these payers are payer_type='commercial' with every rule on
--     product_line='commercial'. Wrong line of business.
--   * Anthem's own "Chronic Care Management and Advance Care Planning --
--     Commercial Health Plans" FAQ states Anthem pays 99490, 99497 and
--     99498 for commercially-insured members after February 23, 2019. Its
--     legal-entity footer names only Connecticut, Maine and New Hampshire;
--     it never mentions Ohio or Community Insurance Company, and it is not
--     reachable from the Ohio provider-news site. Wrong state.
--
-- WHAT THIS SEED THEREFORE ASSERTS
-- Not that these codes are covered. That each payer publishes no code-level
-- coverage determination, and says so itself -- so coverage is plan-specific
-- and must be verified against the member's benefit plan. coverage_status is
-- 'varies', which the code picker badges as such and sorts BELOW genuinely
-- covered codes, and which the denial scorer does not treat as an assertion
-- of coverage.
--
-- That is a smaller claim than "covered", and it is the true one. It also
-- replaces silence: before this, a nurse practitioner choosing Aetna saw an
-- empty code list, which is the vacuum the hand-typed rules were invented to
-- fill.
--
-- Every quote below was re-checked verbatim and contiguous against the
-- document as fetched, at the moment this file was generated.
-- ============================================================================

BEGIN;

INSERT INTO source_document (id, payer_id, url, document_type, title, retrieved_at, content_hash, cms_license_token_used, source_metadata, extracted_at)
VALUES
  ('f2000000-0001-4000-8000-00000000b001'::uuid, 'a0000000-0000-4000-8000-000000000301'::uuid, 'https://es.aetna.com/cpb/medical/data/disclaimer/additionalInfo/additionalinfo.html', 'medical_policy', 'Aetna — Clinical Policy Bulletin Notes / "Important Note" (the coverage disclaimer carried by every medical CPB)', now(), 'sha256:68bb2a8b9840fc3008d205122fe26543c173ec901e501701235133a45729b9b6', FALSE, '{"retrievedVia":"www.aetna.com returns 403 to automated clients; es.aetna.com serves the identical English asset at 200. A browser User-Agent is required: a default curl UA gets 405 from the WAF.","corpusChecked":"all 919 live Aetna medical CPBs (numbers 0001-1300 enumerated) were scanned for these codes"}'::jsonb, now()),
  ('f2000000-0002-4000-8000-00000000b002'::uuid, 'a0000000-0000-4000-8000-000000000303'::uuid, 'https://files.providernews.anthem.com/1938/Place-of-Service-Facility.pdf', 'medical_policy', 'Anthem Blue Cross and Blue Shield (In Ohio: Community Insurance Company) — Reimbursement Policy C-15004, Place of Service: Facility, effective 02/01/2023 (quoted for its standard coverage/reimbursement disclaimer)', now(), 'sha256:95d3a81c7c7463aba6179327d4cfa8f9fa15889429eef5ef16a15b05af026823', FALSE, '{"quotedFor":"the standard Anthem reimbursement-policy disclaimer, which states how coverage is determined; the policy subject (place of service) is not what is cited","ohioScope":"the document names its Ohio underwriter: In Ohio: Community Insurance Company."}'::jsonb, now())
ON CONFLICT (id) DO UPDATE SET
  url = EXCLUDED.url, document_type = EXCLUDED.document_type, title = EXCLUDED.title,
  content_hash = EXCLUDED.content_hash, source_metadata = EXCLUDED.source_metadata,
  retrieved_at = EXCLUDED.retrieved_at, extracted_at = EXCLUDED.extracted_at;

-- Nothing else answers these keys today (that is the whole point), but a
-- later seed must not be able to leave two live rows on one key.
UPDATE payer_rule pr
   SET expiration_date = GREATEST(pr.effective_date, DATE '2023-02-01')
 WHERE pr.expiration_date IS NULL
   AND pr.created_by <> 'extract:coverage-basis-2026-08'
   AND (pr.payer_id, pr.state, pr.code, pr.attribute, pr.product_line) IN (
